import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-07-06","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-07-06","date":"2020-07-06T00:00:00.000Z","updated":"2020-07-07T00:00:00.000Z","tags":["Ceph","分布式存储","Rook","Saif EDM","管理与运维"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-06.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-06.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-07-06.md"};function l(n,a,s,h,g,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2020年7月6日<br><strong>参会人员：</strong> [列出参会人员]<br><strong>缺席人员：</strong> Sebastian, Miguel</p><h4 id="会议议程" tabindex="-1">会议议程 <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程&quot;">​</a></h4><ol><li><strong>NFS配置对象</strong></li><li><strong>Rook Manager测试问题</strong></li><li><strong>Saif EDM的目标和时间线</strong></li></ol><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><ol><li><p><strong>NFS配置对象</strong></p><ul><li>Jeff Leighton提出了该议题，但无人回应。</li></ul></li><li><p><strong>Rook Manager测试问题</strong></p><ul><li>当前Rook的Manager测试失败，该测试针对master分支运行，以便在发布前发现早期破坏性更改。</li><li>发现OSD创建问题，Miguel在上周五提交了PR，希望修复此问题。</li><li>由于Sebastian本周不在，建议暂时禁用该测试，待Sebastian回来后再处理。</li></ul></li><li><p><strong>Saif EDM的目标和时间线</strong></p><ul><li>Saif EDM被正式宣布为不使用Rook安装Ceph的推荐方法。</li><li>文档中已明确指出，安装时推荐使用Saif EDM。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>暂时禁用Rook Manager测试，待Sebastian回来后再处理。</li><li>确认Saif EDM作为非Rook安装Ceph的主要方法。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>禁用Rook Manager测试。</li><li>继续关注Saif EDM的文档和实施情况。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在无其他议题提出后结束。</li><li>下次会议将在Sebastian和Miguel回归后进行。</li></ul><p><strong>会议总结：</strong> 本次会议主要讨论了Rook Manager测试的问题和Saif EDM的实施情况。决定暂时禁用Rook Manager测试，并确认Saif EDM作为安装Ceph的主要方法。下次会议将在关键人员回归后继续进行。</p>',13)])])}const _=e(r,[["render",l]]);export{u as __pageData,_ as default};
